import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Inject,
  Param,
  ParseIntPipe,
  Post,
} from '@nestjs/common';
import { TaskService } from './task.service.js';
import type { Task } from './task.service.js';

/** REST routes generated by `nestvexa make:resource --crud`. Add guards before production. */
@Controller('task')
export class TaskController {
  constructor(@Inject(TaskService) private readonly task: TaskService) {}

  @Get()
  list(): readonly Task[] {
    return this.task.list();
  }

  @Post()
  create(@Body() body: unknown): Task {
    const name: unknown =
      body && typeof body === 'object' ? Reflect.get(body, 'name') : undefined;
    if (typeof name !== 'string' || name.trim().length < 2 || name.length > 80)
      throw new BadRequestException('name must be 2 to 80 characters');
    return this.task.create(name.trim());
  }

  @Delete(':id')
  @HttpCode(204)
  remove(@Param('id', ParseIntPipe) id: number): void {
    this.task.remove(id);
  }
}
